actions.script:
def document = ec.entity.find('mantle.order.OrderHeader').condition('orderId', orderItem.orderId).one()
if (!(document?.documentType in ['QUOTATION', 'SALES_ORDER'])) return
def amounts = ec.resource.script('component://zenith-erp-sales/script/SalesOrderLineAmount.groovy', null,
        [line:orderItem, currency:document.currencyUomId])
results.itemTotal = amounts.total
if (getChildrenTotals) results.itemPlusChildrenTotal = results.itemTotal + (results.childrenTotal ?: 0)
